import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './PayrollPage.css';

export default function PayrollPage({payroll,employees,createPayroll,setPayroll,money}) { const [monthFilter,setMonthFilter]=useState('All'); const visible=payroll.filter(p=>monthFilter==='All'||p.month===monthFilter); const total=visible.reduce((s,p)=>s+Number(p.base||0)+Number(p.incentive||0)-Number(p.deductions||0),0); return <div className="module-page module-page--payroll"><div className="page-heading"><div><div className="eyebrow">PEOPLE OPERATIONS</div><h1>Payroll center</h1><p>Prepare monthly salary drafts, incentives and deductions for review.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>window.print()}>⎙ Print</button><button className="btn primary" onClick={createPayroll}>＋ Generate monthly drafts</button></div></div><div className="stats-grid"><Stat label="Net payroll estimate" value={money(total)} change="Visible payroll entries" icon="₹" tone="purple" foot="Not a bank payment"/><Stat label="Drafts awaiting review" value={visible.filter(p=>p.status==='Draft').length} change="Not approved" icon="◷" tone="orange" foot="Review before paying"/><Stat label="Marked paid" value={visible.filter(p=>p.status==='Paid').length} change="Manual status only" icon="✓" tone="green" foot="No bank integration"/><Stat label="Employees" value={employees.length} change="Current roster" icon="♙" tone="blue" foot="Generated from base salaries"/></div><div className="notice">Payroll is an estimate-only prototype. PF/ESI/TDS, statutory compliance, payslip generation and payment proof must be implemented and reviewed before production use.</div><section className="panel"><div className="panel-head"><div><h3>Salary register</h3><p>Adjust incentive and deductions; then mark status as paid after external payment.</p></div><select className="filter-select" value={monthFilter} onChange={e=>setMonthFilter(e.target.value)}><option>All</option>{[...new Set(payroll.map(p=>p.month))].map(m=><option key={m}>{m}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>MONTH</th><th>BASE SALARY</th><th>INCENTIVE</th><th>DEDUCTIONS</th><th>NET PAY</th><th>STATUS</th></tr></thead><tbody>{visible.map(p=><tr key={p.id}><td><b>{p.employee}</b><small className="cell-sub">{p.employeeId}</small></td><td>{p.month}</td><td>{money(p.base)}</td><td><input className="amount-input" type="number" value={p.incentive} onChange={e=>setPayroll(prev=>prev.map(x=>x.id===p.id?{...x,incentive:Number(e.target.value)}:x))}/></td><td><input className="amount-input" type="number" value={p.deductions} onChange={e=>setPayroll(prev=>prev.map(x=>x.id===p.id?{...x,deductions:Number(e.target.value)}:x))}/></td><td><b>{money(Number(p.base||0)+Number(p.incentive||0)-Number(p.deductions||0))}</b></td><td><select className="inline-select" value={p.status} onChange={e=>setPayroll(prev=>prev.map(x=>x.id===p.id?{...x,status:e.target.value}:x))}><option>Draft</option><option>Approved</option><option>Paid</option></select></td></tr>)}</tbody></table>{!visible.length&&<Empty title="No payroll drafts yet" desc="Generate monthly drafts from the current employee base salaries."/>}</div></section></div>; }
